44	import type { InboxItemKind } from '@/lib/supabase/types'
45	
46	interface InboxItemRowProps {
47	  item: RichInboxItem
48	  urgency: Urgency
49	  isSelected: boolean
50	  isFocused: boolean
51	  members: TeamMember[]
52	  currentUserId: string
53	  onToggleSelect: (id: string) => void
54	  onFocus: (id: string) => void
