58	function typeIcon(type: InboxItemKind) {
59	  switch (type) {
60	    case 'deposit': return <CheckCircle2 className="h-4 w-4 text-stone-brand" aria-hidden="true" />
61	    case 'form': return <FileText className="h-4 w-4 text-stone-brand" aria-hidden="true" />
62	    case 'client': return <UserPlus className="h-4 w-4 text-foreground" aria-hidden="true" />
63	    case 'waitlist': return <Clock className="h-4 w-4 text-stone-brand" aria-hidden="true" />
