107	export function InboxItemRow({
108	  item,
109	  urgency,
110	  isSelected,
111	  isFocused,
112	  members,
113	  currentUserId,
114	  onToggleSelect,
115	  onFocus,
116	  onRefresh,
117	}: InboxItemRowProps) {
118	  const [isPending, startTransition] = useTransition()
119	  const meta = URGENCY_META[urgency]
120	  const ts = new Date(item.timestamp)
121	  const isRecent = Date.now() - ts.getTime() < 24 * 60 * 60 * 1000
122	
123	  // Extract the raw UUID from composite id like "booking-<uuid>"
124	  const rawId = item.id.replace(/^(booking|consent|waitlist|client)-/, '')
125	
126	  const assignedMember = members.find((m) => m.userId === item.assignedTo) ?? null
127	
128	  function handleCta() {
129	    startTransition(async () => {
130	      let result: { ok: boolean; error?: string }
131	
132	      if (item.type === 'deposit') {
133	        result = await sendDepositReminderAction(rawId)
134	        if (result.ok) {
135	          toast.success('Deposit reminder sent')
136	          onRefresh()
137	        } else {
138	          toast.error(result.error ?? 'Failed to send reminder')
139	        }
140	        return
141	      }
142	
143	      if (item.type === 'form') {
144	        result = await resendFormLinkAction(rawId)
145	        if (result.ok) {
146	          toast.success('Form link resent')
147	          onRefresh()
148	        } else {
149	          toast.error(result.error ?? 'Failed to resend link')
150	        }
151	        return
152	      }
153	
154	      if (item.type === 'client') {
155	        result = await sendWelcomeAction(rawId)
156	        if (result.ok) {
157	          toast.success('Welcome email sent')
158	          onRefresh()
159	        } else {
160	          toast.error(result.error ?? 'Failed to send welcome email')
161	        }
162	        return
163	      }
164	
165	      if (item.type === 'waitlist') {
166	        // Waitlist CTA opens the booking drawer — we just navigate to bookings/new
167	        // with a query param. The drawer is pre-filled by the server action on that page.
168	        window.location.href = `/bookings/new?waitlist=${rawId}`
169	        return
170	      }
171	
172	      if (item.type === 'unread-message') {
173	        // Navigate to the client comms tab
174	        window.location.href = item.actionHref
175	      }
176	    })
177	  }
178	
179	  function handleResolve() {
180	    startTransition(async () => {
181	      const result = await resolveInboxItemAction(item.type, rawId)
182	      if (result.ok) {
183	        toast.success('Marked as resolved')
184	        onRefresh()
185	      } else {
186	        toast.error(result.error ?? 'Failed to resolve')
187	      }
188	    })
189	  }
190	
191	  function handleArchive() {
192	    startTransition(async () => {
193	      const result = await archiveInboxItemAction(item.type, rawId)
194	      if (result.ok) {
195	        toast.success('Archived')
196	        onRefresh()
197	      } else {
198	        toast.error(result.error ?? 'Failed to archive')
199	      }
200	    })
201	  }
202	
203	  async function handleAssign(userId: string | null) {
204	    const result = await assignInboxItemAction(item.type, rawId, userId)
205	    if (result.ok) {
206	      toast.success(userId ? 'Assigned' : 'Unassigned')
207	      onRefresh()
208	    } else {
209	      toast.error(result.error ?? 'Failed to assign')
210	    }
211	  }
212	
213	  return (
214	    <div
215	      role="listitem"
216	      data-inbox-item-id={item.id}
217	      data-selected={isSelected}
218	      onClick={() => onFocus(item.id)}
219	      onKeyDown={(e) => {
