234	    >
235	      {/* Checkbox */}
236	      <Checkbox
237	        checked={isSelected}
238	        onCheckedChange={() => onToggleSelect(item.id)}
239	        onClick={(e) => e.stopPropagation()}
240	        aria-label={`Select ${item.title}`}
241	        className="shrink-0"
