248	      />
249	
250	      {/* Type icon */}
251	      <div className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-full', typeBg(item.type))}>
252	        {typeIcon(item.type)}
253	      </div>
254	
255	      {/* Content */}
256	      <div className="min-w-0 flex-1">
