288	        aria-label={`${ctaLabel(item.type)} for ${item.title}`}
289	      >
290	        {ctaIcon(item.type)}
291	        <span className="hidden md:inline">{ctaLabel(item.type)}</span>
292	      </Button>
293	
294	      {/* Mobile: icon-only CTA */}
295	      <Button
296	        variant="outline"
297	        size="sm"
298	        onClick={(e) => { e.stopPropagation(); handleCta() }}
299	        disabled={isPending}
300	        className="shrink-0 h-7 w-7 p-0 sm:hidden"
301	        aria-label={ctaLabel(item.type)}
302	      >
303	        {ctaIcon(item.type)}
304	      </Button>
305	
306	      {/* Kebab menu */}
307	      <DropdownMenu>
308	        <DropdownMenuTrigger
309	          render={
310	            <Button
311	              variant="ghost"
312	              size="sm"
313	              onClick={(e) => e.stopPropagation()}
314	              className="h-7 w-7 shrink-0 p-0 text-muted-foreground/60 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100"
315	              aria-label="More options"
316	            >
317	              <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
318	            </Button>
319	          }
320	        />
321	        <DropdownMenuContent align="end" side="bottom">
322	          <DropdownMenuItem
323	            onClick={(e) => { e.stopPropagation(); handleResolve() }}
324	            className="gap-2 text-xs"
325	          >
326	            <UserCheck className="h-3.5 w-3.5" aria-hidden="true" />
327	            Mark resolved
328	          </DropdownMenuItem>
329	          <DropdownMenuItem
330	            onClick={(e) => { e.stopPropagation(); handleArchive() }}
331	            className="gap-2 text-xs"
332	          >
333	            <Archive className="h-3.5 w-3.5" aria-hidden="true" />
334	            Archive
335	          </DropdownMenuItem>
336	          <DropdownMenuSeparator />
337	          {/* View link */}
338	          <DropdownMenuItem
339	            className="gap-2 text-xs"
340	            render={<Link href={item.actionHref} onClick={(e) => e.stopPropagation()} />}
341	          >
342	            View details
343	          </DropdownMenuItem>
344	        </DropdownMenuContent>
345	      </DropdownMenu>
346	
347	      {/* Assign picker — hidden on mobile */}
348	      <div className="hidden sm:block" onClick={(e) => e.stopPropagation()}>
349	        <AssignUserPicker
350	          members={members}
351	          currentUserId={currentUserId}
352	          currentAssignee={item.assignedTo}
353	          onAssign={handleAssign}
354	          compact
355	        />
356	      </div>
357	    </div>
358	  )
359	}
