/**
 * Urgency computation for inbox items.
 *
 * 3-tier system:
 *   overdue    — revenue-blocking items requiring immediate action
 *   today      — time-sensitive items due today or within 48h
 *   this_week  — this-week items, lower pressure
 *   older      — items 7+ days old, collapsed accordion
 *
 * Brand colors (Bone/Onyx/Stone/Rust only):
 *   overdue   → Rust (--color-destructive)
 *   today     → --color-warning (semantic token from globals.css)
 *   this_week → --color-accent (Rust @ 8%)
 *   older     → Stone muted
 */

import type { InboxItemKind } from '@/lib/supabase/types'

export type Urgency = 'overdue' | 'today' | 'this_week' | 'older'

export interface UrgencyMeta {
  label: string
  /** Tailwind text colour class — brand tokens only */
  textClass: string
  /** Tailwind bg colour class for the dot */
  dotClass: string
  /** Tailwind border colour class for the group card */
  borderClass: string
  /** Tailwind bg for the group header badge */
  badgeBg: string
  /** Whether to use Rust-coloured action buttons */
  isUrgent: boolean
}

export const URGENCY_META: Record<Urgency, UrgencyMeta> = {
  overdue: {
    label: 'OVERDUE',
    textClass: 'text-destructive',
    dotClass: 'bg-destructive',
    borderClass: 'border-destructive/25',
    badgeBg: 'bg-destructive/10 text-destructive',
    isUrgent: true,
  },
  today: {
    label: 'TODAY',
    textClass: 'text-[var(--color-warning-foreground)]',
    dotClass: 'bg-[var(--color-warning)]',
    borderClass: 'border-[var(--color-warning)]/20',
    badgeBg: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
    isUrgent: false,
  },
  this_week: {
    label: 'THIS WEEK',
    textClass: 'text-muted-foreground',
    dotClass: 'bg-muted-foreground/50',
    borderClass: 'border-border/40',
    badgeBg: 'bg-muted text-muted-foreground',
    isUrgent: false,
  },
  older: {
    label: 'OLDER',
    textClass: 'text-muted-foreground/60',
    dotClass: 'bg-muted-foreground/30',
    borderClass: 'border-border/20',
    badgeBg: 'bg-muted/50 text-muted-foreground/60',
    isUrgent: false,
  },
}

export const URGENCY_ORDER: Urgency[] = ['overdue', 'today', 'this_week', 'older']

/** Items in OVERDUE tier for a tab — rendered as Rust subcount on tab badge */
export function isOverdueType(kind: InboxItemKind): boolean {
  return (
    kind === 'deposit' ||
    kind === 'form' ||
    kind === 'booking-conflict' ||
    kind === 'failed-payment'
  )
}

export interface InboxItemForUrgency {
  type: InboxItemKind
  /** ISO timestamp of the item itself (created_at or updated_at) */
  timestamp: string
  /** For deposit / form / conflict items: the booking's scheduled_at — ISO string */
  scheduledAt?: string | null
}

/**
 * Compute urgency for a single inbox item.
 * All comparisons use Date.now().
 */
export function computeUrgency(item: InboxItemForUrgency): Urgency {
  const now = Date.now()
  const h24 = 24 * 60 * 60 * 1000
  const h48 = 48 * 60 * 60 * 1000
  const d7 = 7 * 24 * 60 * 60 * 1000

  const itemAge = now - new Date(item.timestamp).getTime()

  // ── OVERDUE tier ──────────────────────────────────────────────
  if (item.type === 'booking-conflict') return 'overdue'
  if (item.type === 'failed-payment') return 'overdue'

  if (item.type === 'deposit') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      // < 24h until session → OVERDUE (revenue blocking)
      if (msUntil >= 0 && msUntil < h24) return 'overdue'
      // 24–48h → TODAY
      if (msUntil >= 0 && msUntil < h48) return 'today'
    }
    return 'this_week'
  }

  if (item.type === 'form') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      // Consent unsigned < 24h before session → OVERDUE
      if (msUntil >= 0 && msUntil < h24) return 'overdue'
    }
    // Form unsigned for >24h → this_week; else today
    if (itemAge > h24) return 'this_week'
    return 'today'
  }

  // ── TODAY tier ────────────────────────────────────────────────
  if (item.type === 'low-inventory') return 'today'
  if (item.type === 'guest-residency') {
    // ≤48h → today; ≤7d → this_week
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil <= h48) return 'today'
      if (msUntil >= 0 && msUntil <= d7) return 'this_week'
    }
    return 'this_week'
  }

  if (item.type === 'waitlist') {
    if (itemAge < h24) return 'today'
    return 'older'
  }

  // ── THIS WEEK tier ────────────────────────────────────────────
  if (item.type === 'client') {
    if (itemAge < d7) return 'this_week'
    return 'older'
  }

  if (item.type === 'review-request') return 'this_week'
  if (item.type === 'client-birthday') return 'this_week'
  if (item.type === 'artist-gap') return 'this_week'

  if (item.type === 'unread-message') {
    if (itemAge < h24) return 'today'
    if (itemAge < d7) return 'this_week'
    return 'older'
  }

  return 'older'
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { RichInboxItem, InboxItemType } from '@/components/inbox/InboxClient'
import type { TeamMember } from '@/components/inbox/AssignUserPicker'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const now = new Date()
  const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString()
  const twoDaysOut = new Date(now.getTime() + 48 * 60 * 60 * 1000).toISOString()
  const sevenDaysOut = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString()
  const fortyEightHoursAgo = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString()
  const threeDaysOut = new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000).toISOString()
  const todayStart = new Date(now)
  todayStart.setHours(0, 0, 0, 0)
  const todayEnd = new Date(now)
  todayEnd.setHours(23, 59, 59, 999)
  // Birthday month/day window: today through +3 days
  const mmDdToday = `${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`

  // Fetch all data sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
    assignmentsRes,
    membersRes,
    unreadConversationsRes,
    // New triggers
    conflictingBookingsRes,
    artistGapsRes,
    lowInventoryRes,
    birthdayClientsRes,
    failedPaymentsRes,
    guestResidencyRes,
    reviewCandidatesRes,
  ] = await Promise.all([
    // 1. Pending bookings — deposit unpaid
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'pending')
      .eq('deposit_paid', false)
      .order('scheduled_at', { ascending: true })
      .limit(50),

    // 2. Bookings with consent required but not yet signed (last 7d)
    supabase
      .from('bookings')
      .select('id, client_id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('consent_required', true)
      .is('consent_signed_at', null)
      .gte('created_at', sevenDaysAgo)
      .order('scheduled_at', { ascending: true })
      .limit(30),

    // 3. Waitlist entries (last 24h)
    supabase
      .from('waitlist_entries')
      .select('id, client_id, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(20),

    // 4. New clients (last 7d)
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('archived_at', null)
      .order('created_at', { ascending: false })
      .limit(10),

    // 5. Inbox assignments — active only
    supabase
      .from('inbox_assignments')
      .select('item_kind, item_id, assigned_to, snoozed_until, archived_at, resolved_at')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .is('resolved_at', null)
      .limit(500),

    // 6. Studio members for assignment picker
    supabase
      .from('studio_members')
      .select('user_id, role, profiles(full_name, avatar_url)')
      .eq('studio_id', studioId)
      .is('deactivated_at', null),

    // 7. Unread message conversations
    supabase
      .from('conversations')
      .select('id, client_id, display_name, last_message_preview, last_message_at, unread_count, channel')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0)
      .order('last_message_at', { ascending: false })
      .limit(50),

    // 8. Booking conflicts — bookings in same time window for same artist (detect via overlapping scheduled_at/end_at)
    //    Simplified: fetch all confirmed/pending bookings for today and find artist duplication.
    //    The DB exclusion constraint prevents true double-books; this catches status edge cases.
    supabase
      .from('bookings')
      .select('id, artist_id, scheduled_at, end_at, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .in('status', ['pending', 'confirmed'])
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', sevenDaysOut)
      .order('scheduled_at', { ascending: true })
      .limit(200),

    // 9. Artist schedule gaps — members who are active artists with open schedule blocks >2h, 3+ days out
    //    Scaffold only: query artists who have NO bookings between 3 and 7 days out during working hours.
    //    We pull artists and their booking counts in that window.
    supabase
      .from('studio_members')
      .select('user_id, profiles(full_name)')
      .eq('studio_id', studioId)
      .in('role', ['artist', 'admin', 'owner'])
      .is('deactivated_at', null)
      .limit(20),

    // 10. Low inventory — items where current_stock <= min_threshold
    supabase
      .from('inventory_items')
      .select('id, name, category, current_stock, min_threshold, updated_at')
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .filter('current_stock', 'lte', 0) // start with empty stock as baseline; refined below
      .order('current_stock', { ascending: true })
      .limit(20),

    // 11. Client birthdays — DOB today or next 3 days
    //     date_of_birth is stored as 'YYYY-MM-DD'; we compare MM-DD portion
    supabase
      .from('clients')
      .select('id, first_name, last_name, date_of_birth, created_at')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .not('date_of_birth', 'is', null)
      .limit(100),

    // 12. Failed payments — bookings where deposit was attempted but not paid,
    //     and payment ID exists (indicating a failed charge)
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('deposit_paid', false)
      .not('deposit_payment_id', 'is', null)
      .neq('status', 'cancelled')
      .order('created_at', { ascending: false })
      .limit(20),

    // 13. Guest residency ending — studio_members with role=guest_artist whose ends_at is within 7 days
    supabase
      .from('studio_members')
      .select('id, user_id, ends_at, profiles(full_name)')
      .eq('studio_id', studioId)
      .eq('role', 'guest_artist')
      .is('deactivated_at', null)
      .not('ends_at', 'is', null)
      .lte('ends_at', sevenDaysOut)
      .gte('ends_at', now.toISOString())
      .limit(10),

    // 14. Review request candidates — completed bookings 48h+ ago, no review request sent
    supabase
      .from('bookings')
      .select('id, client_id, completed_at: updated_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'completed')
      .lte('updated_at', fortyEightHoursAgo)
      .gte('updated_at', sevenDaysAgo)
      // TODO: add .is('review_request_sent_at', null) once column exists
      .order('updated_at', { ascending: false })
      .limit(10),
  ])

  // Build assignment map: key = `${kind}-${item_id}`
  type AssignmentState = {
    assignedTo: string | null
    snoozedUntil: string | null
    archivedAt: string | null
    resolvedAt: string | null
  }

  const assignmentMap = new Map<string, AssignmentState>()
  for (const a of assignmentsRes.data ?? []) {
    assignmentMap.set(`${a.item_kind}-${a.item_id}`, {
      assignedTo: a.assigned_to,
      snoozedUntil: a.snoozed_until,
      archivedAt: a.archived_at,
      resolvedAt: a.resolved_at,
    })
  }

  function getAssignment(kind: InboxItemType, itemId: string): AssignmentState {
    return assignmentMap.get(`${kind}-${itemId}`) ?? {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }
  }

  // Normalize into RichInboxItem[]
  const items: RichInboxItem[] = []

  // ── Trigger 1: Pending bookings (deposit overdue) ──
  for (const booking of pendingBookingsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('deposit', booking.id)

    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: 'Deposit pending',
      subtitle: clientName,
      actionLabel: 'Send reminder',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      priority: booking.scheduled_at &&
        new Date(booking.scheduled_at).getTime() - Date.now() < 24 * 60 * 60 * 1000
        ? 'high'
        : 'med',
      ...a,
    })
  }

  // ── Trigger 2: Unsigned consent forms ──
  for (const booking of consentSubmissionsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('form', booking.id)

    items.push({
      id: `consent-${booking.id}`,
      type: 'form' as InboxItemType,
      title: 'Consent form unsigned',
      subtitle: clientName,
      actionLabel: 'Resend link',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      priority: booking.scheduled_at &&
        new Date(booking.scheduled_at).getTime() - Date.now() < 24 * 60 * 60 * 1000
        ? 'high'
        : 'med',
      ...a,
    })
  }

  // ── Trigger 3: Waitlist entries ──
  for (const entry of waitlistRes.data ?? []) {
    const clientRow = Array.isArray(entry.clients) ? entry.clients[0] : entry.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('waitlist', entry.id)

    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: 'New waitlist signup',
      subtitle: clientName,
      actionLabel: 'Offer slot',
      actionHref: `/clients/${entry.client_id}`,
      timestamp: entry.created_at,
      scheduledAt: null,
      priority: 'med',
      ...a,
    })
  }

  // ── Trigger 4: New clients ──
  for (const client of newClientsRes.data ?? []) {
    const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
    const a = getAssignment('client', client.id)

    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: 'New client',
      subtitle: clientName,
      actionLabel: 'Send welcome',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
      scheduledAt: null,
      priority: 'med',
      ...a,
    })
  }

  // ── Trigger 5: Unread conversations ──
  for (const conv of unreadConversationsRes.data ?? []) {
    const preview = conv.last_message_preview
      ? String(conv.last_message_preview).slice(0, 80)
      : 'New message'
    const clientId = conv.client_id as string | null
    const a = clientId ? getAssignment('unread-message', String(conv.id)) : {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }

    items.push({
      id: `conv-${conv.id as string}`,
      type: 'unread-message' as InboxItemType,
      title: String(conv.display_name ?? 'Message'),
      subtitle: preview,
      actionLabel: 'Reply',
      actionHref: clientId ? `/clients/${clientId}?tab=comms` : '/inbox',
      timestamp: conv.last_message_at as string ?? new Date().toISOString(),
      scheduledAt: null,
      priority: 'med',
      ...a,
    })
  }

  // ── Trigger 6: Booking conflicts ──
  // Group by artist_id, detect overlapping scheduled_at / end_at
  if (conflictingBookingsRes.data) {
    const byArtist = new Map<string, typeof conflictingBookingsRes.data>()
    for (const b of conflictingBookingsRes.data) {
      const existing = byArtist.get(b.artist_id) ?? []
      existing.push(b)
      byArtist.set(b.artist_id, existing)
    }

    const seenConflictIds = new Set<string>()

    for (const [, artistBookings] of byArtist) {
      const sorted = [...artistBookings].sort(
        (a, b) => new Date(a.scheduled_at).getTime() - new Date(b.scheduled_at).getTime(),
      )
      for (let i = 0; i < sorted.length - 1; i++) {
        const cur = sorted[i]!
        const next = sorted[i + 1]!
        const curEnd = new Date(cur.end_at ?? cur.scheduled_at).getTime()
        const nextStart = new Date(next.scheduled_at).getTime()
        if (curEnd > nextStart && !seenConflictIds.has(cur.id)) {
          seenConflictIds.add(cur.id)
          const clientRow = Array.isArray(cur.clients) ? cur.clients[0] : cur.clients
          const clientName = clientRow
            ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
            : 'Client'
          const a = getAssignment('booking-conflict', cur.id)

          items.push({
            id: `conflict-${cur.id}`,
            type: 'booking-conflict' as InboxItemType,
            title: 'Booking conflict',
            subtitle: `${clientName} — overlaps with next appointment`,
            actionLabel: 'View booking',
            actionHref: `/bookings/${cur.id}`,
            timestamp: cur.created_at,
            scheduledAt: cur.scheduled_at,
            priority: 'high',
            ...a,
          })
        }
      }
    }
  }

  // ── Trigger 7: Low inventory ──
  // Re-query with proper filter (current_stock <= min_threshold)
  const lowInventoryItems = (lowInventoryRes.data ?? []).filter(
    (item) => item.current_stock <= item.min_threshold,
  )
  for (const inv of lowInventoryItems) {
    const a = getAssignment('low-inventory', inv.id)

    items.push({
      id: `inv-${inv.id}`,
      type: 'low-inventory' as InboxItemType,
      title: `Low inventory: ${inv.name}`,
      subtitle: `${inv.current_stock} left (threshold: ${inv.min_threshold}) · ${inv.category}`,
      actionLabel: 'View inventory',
      actionHref: `/inventory`,
      timestamp: inv.updated_at,
      scheduledAt: null,
      priority: inv.current_stock === 0 ? 'high' : 'med',
      ...a,
    })
  }

  // ── Trigger 8: Client birthdays (DOB today → +3 days) ──
  if (birthdayClientsRes.data) {
    const nowMs = Date.now()
    for (const client of birthdayClientsRes.data) {
      if (!client.date_of_birth) continue
      const mmDd = client.date_of_birth.slice(5) // "MM-DD"
      // Check if mmDd falls in today → +3 days window
      let isBirthday = false
      for (let dayOffset = 0; dayOffset <= 3; dayOffset++) {
        const checkDate = new Date(nowMs + dayOffset * 24 * 60 * 60 * 1000)
        const checkMmDd = `${String(checkDate.getMonth() + 1).padStart(2, '0')}-${String(checkDate.getDate()).padStart(2, '0')}`
        if (mmDd === checkMmDd) { isBirthday = true; break }
      }
      if (!isBirthday) continue

      const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
      const a = getAssignment('client-birthday', client.id)

      items.push({
        id: `birthday-${client.id}`,
        type: 'client-birthday' as InboxItemType,
        title: `Birthday: ${clientName}`,
        subtitle: `DOB ${client.date_of_birth} — a great time to reach out`,
        actionLabel: 'View client',
        actionHref: `/clients/${client.id}`,
        timestamp: client.created_at,
        scheduledAt: null,
        priority: 'med',
        ...a,
      })
    }
  }

  // ── Trigger 9: Failed payments ──
  for (const booking of failedPaymentsRes.data ?? []) {
    const a = getAssignment('failed-payment', booking.id)
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'

    items.push({
      id: `payment-${booking.id}`,
      type: 'failed-payment' as InboxItemType,
      title: 'Failed deposit charge',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      priority: 'high',
      ...a,
    })
  }

  // ── Trigger 10: Guest artist residency ending ──
  for (const member of guestResidencyRes.data ?? []) {
    if (!member.ends_at) continue
    const profileRow = Array.isArray(member.profiles) ? member.profiles[0] : member.profiles
    const artistName = profileRow?.full_name ?? 'Guest artist'
    const a = getAssignment('guest-residency', member.id)
    const msUntil = new Date(member.ends_at).getTime() - Date.now()
    const daysLeft = Math.ceil(msUntil / (24 * 60 * 60 * 1000))

    items.push({
      id: `guest-${member.id}`,
      type: 'guest-residency' as InboxItemType,
      title: 'Guest residency ending',
      subtitle: `${artistName} — ${daysLeft} day${daysLeft !== 1 ? 's' : ''} left`,
      actionLabel: 'View artist',
      actionHref: `/guest-artists`,
      timestamp: now.toISOString(),
      scheduledAt: member.ends_at,
      priority: daysLeft <= 2 ? 'high' : 'med',
      ...a,
    })
  }

  // ── Trigger 11: Review request candidates ──
  // TODO: add review_request_sent_at column to bookings table (Dato migration needed).
  // For now, all completed bookings 48h+ ago surface as candidates.
  for (const booking of reviewCandidatesRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('review-request', booking.id)

    items.push({
      id: `review-${booking.id}`,
      type: 'review-request' as InboxItemType,
      title: 'Request a review',
      subtitle: clientName,
      actionLabel: 'Send request',
      actionHref: `/clients/${booking.client_id}`,
      timestamp: booking.completed_at as string,
      scheduledAt: null,
      priority: 'med',
      ...a,
    })
  }

  // ── Trigger 12: Artist schedule gaps ──
  // TODO: This requires cross-referencing artists against bookings in 3–7 day window.
  // Skipping for v1 — needs a Dato RPC to compute gaps efficiently.
  // Scaffold: artistGapsRes contains artist members; gap detection deferred.
  void artistGapsRes // consumed but not processed — see TODO above
  void mmDdToday // used in birthday block above

  // Filter snoozed items
  const nowIso = now.toISOString()
  const activeitems = items.filter((item) => {
    if (!item.snoozedUntil) return true
    return item.snoozedUntil < nowIso
  })

  // Sort by timestamp descending
  activeitems.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list for assignment picker
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={activeitems}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

