// ─── Types ────────────────────────────────────────────────────

export type InboxItemType = InboxItemKind

export type ItemPriority = 'high' | 'med'

export interface InboxItem {
  id: string
  type: InboxItemType
  title: string
  subtitle: string
  actionLabel: string
  actionHref: string
  timestamp: string
  priority: ItemPriority
}

/** Extended item with urgency-related fields and assignment state */
export interface RichInboxItem extends InboxItem {
  scheduledAt: string | null
  assignedTo: string | null
  resolvedAt: string | null
  archivedAt: string | null
  snoozedUntil: string | null
}

interface InboxClientProps {
  items: RichInboxItem[]
  members: TeamMember[]
  currentUserId: string
  currentPlan: PlanTier
  currentRole: NavRole
}

type TabKey = 'all' | 'deposits' | 'forms' | 'clients' | 'bookings' | 'inventory' | 'inquiries'

const VALID_TABS: TabKey[] = ['all', 'deposits', 'forms', 'clients', 'bookings', 'inventory', 'inquiries']

interface SelectedItem {
  id: string
  type: InboxItemKind
}

function tabFilter(item: RichInboxItem, tab: TabKey): boolean {
  switch (tab) {
    case 'all': return true
    case 'deposits': return item.type === 'deposit' || item.type === 'failed-payment'
    case 'forms': return item.type === 'form'
    case 'clients':
      return (
        item.type === 'client' ||
        item.type === 'waitlist' ||
        item.type === 'client-birthday' ||
        item.type === 'review-request'
      )
    case 'bookings':
      return (
        item.type === 'booking-conflict' ||
        item.type === 'artist-gap' ||
        item.type === 'guest-residency'
      )
    case 'inventory': return item.type === 'low-inventory'
    case 'inquiries': return item.type === 'unread-message'
    default: return true
  }
}

// ─── Component ────────────────────────────────────────────────

export function InboxClient({
  items,
  members,
  currentUserId,
  currentPlan,
  currentRole,
}: InboxClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const rawTab = searchParams.get('tab')
  const activeTab: TabKey = VALID_TABS.includes(rawTab as TabKey) ? (rawTab as TabKey) : 'all'

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [focusedId, setFocusedId] = useState<string | null>(null)
  const [showCheatsheet, setShowCheatsheet] = useState(false)
  const [showArchived, setShowArchived] = useState(false)

  // Filter out archived/resolved unless showArchived
  const activeItems: RichInboxItem[] = items.filter((item) => {
    if (showArchived) return true
    return item.archivedAt === null && item.resolvedAt === null
  })

  // Build tab metadata: count + overdue subcount
  function buildTabMeta(tab: TabKey) {
    const filtered = activeItems.filter((i) => tabFilter(i, tab))
    const total = filtered.length
    const overdue = filtered.filter((i) => isOverdueType(i.type)).length
    return { total, overdue }
  }

  const tabMetas: Record<TabKey, { total: number; overdue: number }> = {
    all: buildTabMeta('all'),
    deposits: buildTabMeta('deposits'),
    forms: buildTabMeta('forms'),
    clients: buildTabMeta('clients'),
    bookings: buildTabMeta('bookings'),
    inventory: buildTabMeta('inventory'),
    inquiries: buildTabMeta('inquiries'),
  }

  // Tab definitions — rendered inline (not via PageTabs to support overdue subcounts)
  const TAB_DEFS: { key: TabKey; label: string; href: string }[] = [
    { key: 'all', label: 'All', href: '/inbox' },
    { key: 'deposits', label: 'Deposits', href: '/inbox?tab=deposits' },
    { key: 'forms', label: 'Forms', href: '/inbox?tab=forms' },
    { key: 'clients', label: 'Clients', href: '/inbox?tab=clients' },
    { key: 'bookings', label: 'Bookings', href: '/inbox?tab=bookings' },
    { key: 'inventory', label: 'Inventory', href: '/inbox?tab=inventory' },
    { key: 'inquiries', label: 'Inquiries', href: '/inbox?tab=inquiries' },
  ]

  // Filter by active tab
  const tabFiltered: RichInboxItem[] = activeItems.filter((i) => tabFilter(i, activeTab))

  // Group by urgency
  const groups: Record<Urgency, RichInboxItem[]> = {
    overdue: [],
    today: [],
    this_week: [],
    older: [],
  }

  for (const item of tabFiltered) {
    const urgency = computeUrgency({
      type: item.type,
      timestamp: item.timestamp,
      scheduledAt: item.scheduledAt,
    })
    groups[urgency].push(item)
  }

  // Flat ordered list for keyboard nav
  const orderedItems: RichInboxItem[] = URGENCY_ORDER.flatMap((u) => groups[u])

  // ── Selection helpers ──
  const toggleSelect = useCallback((id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const clearSelection = useCallback(() => setSelected(new Set()), [])

  // ── Focus helpers ──
  const focusItem = useCallback((id: string) => {
    setFocusedId(id)
    const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${id}"]`)
    el?.focus()
    el?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [])

  // ── Refresh ──
  const refresh = useCallback(() => {
    router.refresh()
  }, [router])

  // ── Keyboard shortcuts ──
  useInboxShortcuts({
    onNavigateDown: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const next = idx === -1 ? 0 : Math.min(idx + 1, orderedItems.length - 1)
      const nextItem = orderedItems[next]
      if (nextItem) focusItem(nextItem.id)
    },
    onNavigateUp: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const prev = idx <= 0 ? 0 : idx - 1
      const prevItem = orderedItems[prev]
      if (prevItem) focusItem(prevItem.id)
    },
    onArchiveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onSnoozeFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="Snooze item"]')?.click()
    },
    onMarkUnreadFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="Mark unread"]')?.click()
    },
    onAssignFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="Assign to team member"]')?.click()
    },
    onArchiveAllSelected: () => {
      if (selected.size === 0) return
      document.querySelector<HTMLElement>('[aria-label="Archive all selected"]')?.click()
    },
    onResolveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onToggleFocusedCheckbox: () => {
      if (focusedId) toggleSelect(focusedId)
    },
    onShowCheatsheet: () => setShowCheatsheet(true),
  })

  const selectedItems: SelectedItem[] = orderedItems
    .filter((i) => selected.has(i.id))
    .map((i) => ({ id: i.id, type: i.type }))

  const hasNonEmpty = URGENCY_ORDER.some((u) => groups[u].length > 0)
  const allEmpty = !hasNonEmpty
  const overdueEmpty = groups.overdue.length === 0
  const totalMeta = tabMetas[activeTab]

  return (
    <>
      <PageShell>
        {/* Title — no breadcrumb, Inbox is top-level */}
        <PageHeader
          title="Inbox"
          description="Action items that need your attention"
          actions={
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowCheatsheet(true)}
              aria-label="Show keyboard shortcuts"
              className="h-8 w-8 p-0 text-muted-foreground/60 hover:text-foreground"
            >
              <Keyboard className="h-4 w-4" aria-hidden="true" />
            </Button>
          }
        />

        {/* Custom tab bar with count + overdue subcount badges */}
        <PageViews>
          <nav
            role="tablist"
            aria-label="Inbox categories"
            className="flex gap-0.5 overflow-x-auto pb-px"
          >
            {TAB_DEFS.map((tab) => {
              const meta = tabMetas[tab.key]
              const isActive = activeTab === tab.key
              return (
                <a
                  key={tab.key}
                  href={tab.href}
                  role="tab"
                  aria-selected={isActive}
                  className={cn(
                    'inline-flex shrink-0 items-center gap-1.5 rounded-md px-3 py-1.5 text-[13px] font-medium transition-colors',
                    isActive
                      ? 'bg-background text-foreground shadow-soft'
                      : 'text-muted-foreground hover:text-foreground hover:bg-muted/30',
                  )}
                >
                  <span>{tab.label}</span>
                  {meta.total > 0 && (
                    <span
                      className={cn(
                        'inline-flex items-center gap-1 rounded-full px-1.5 py-px text-[10px] font-semibold tabular-nums',
                        isActive ? 'bg-muted text-muted-foreground' : 'bg-muted/50 text-muted-foreground/70',
                      )}
                    >
                      {meta.total}
                      {meta.overdue > 0 && (
                        <span
                          className="text-destructive font-bold"
                          title={`${meta.overdue} overdue`}
                          aria-label={`${meta.overdue} overdue`}
                        >
                          ·{meta.overdue}
                        </span>
                      )}
                    </span>
                  )}
                </a>
              )
            })}
          </nav>
        </PageViews>

        {/* Batch action bar */}
        {selected.size > 0 && (
          <div aria-live="polite">
            <BatchActionBar
              selected={selectedItems}
              members={members}
              currentUserId={currentUserId}
              onClear={clearSelection}
              onRefresh={refresh}
            />
          </div>
        )}

        <div className="flex items-center justify-end">
          <button
            type="button"
            onClick={() => setShowArchived((v) => !v)}
            className="text-[11px] text-muted-foreground/60 hover:text-muted-foreground transition-colors"
          >
            {showArchived ? 'Hide archived' : 'Show archived & resolved'}
          </button>
        </div>

        <div className="flex-1 space-y-3">
          {allEmpty ? (
            /* Full inbox-zero celebration state */
            <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
              <p className="font-serif italic text-3xl text-foreground/80">
                Inbox zero · Studio is dialed in.
              </p>
              <p className="text-sm text-muted-foreground max-w-xs">
                {activeTab === 'all'
                  ? 'No pending action items. New signals appear here automatically.'
                  : 'Nothing in this category right now.'}
              </p>
            </div>
          ) : (
            <>
              {/* OVERDUE empty but others populated */}
              {overdueEmpty && totalMeta.total > 0 && (
                <p className="text-[12px] text-muted-foreground/70 italic px-1">
                  Nothing overdue. Well done.
                </p>
              )}

              {URGENCY_ORDER.map((urgency) => {
                const groupItems = groups[urgency]
                if (groupItems.length === 0) return null
                const defaultExpanded = urgency === 'overdue' || urgency === 'today'

                return (
                  <UrgencyGroup
                    key={urgency}
                    urgency={urgency}
                    count={groupItems.length}
                    defaultExpanded={defaultExpanded}
                  >
                    {groupItems.map((item) => (
                      <InboxItemRow
                        key={item.id}
                        item={item}
                        urgency={urgency}
                        isSelected={selected.has(item.id)}
                        isFocused={focusedId === item.id}
                        members={members}
                        currentUserId={currentUserId}
                        onToggleSelect={toggleSelect}
                        onFocus={setFocusedId}
                        onRefresh={refresh}
                      />
                    ))}
                  </UrgencyGroup>
                )
              })}
            </>
          )}
        </div>
      </PageShell>

      {/* Keyboard shortcuts cheatsheet */}
      <Dialog open={showCheatsheet} onOpenChange={setShowCheatsheet}>
        <DialogContent className="max-w-xs">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">Keyboard shortcuts</DialogTitle>
          </DialogHeader>
          <div className="mt-2 space-y-1.5">
            {INBOX_SHORTCUTS.map(({ key, description }) => (
              <div key={key} className="flex items-center justify-between gap-4">
                <span className="text-xs text-muted-foreground">{description}</span>
                <kbd className="inline-flex h-5 min-w-[1.25rem] items-center justify-center rounded border border-border/60 bg-muted px-1 text-[10px] font-mono text-foreground">
                  {key}
                </kbd>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState } from 'react'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Urgency } from '@/lib/inbox/urgency'
import { URGENCY_META } from '@/lib/inbox/urgency'

interface UrgencyGroupProps {
  urgency: Urgency
  count: number
  defaultExpanded?: boolean
  children: React.ReactNode
}

export function UrgencyGroup({
  urgency,
  count,
  defaultExpanded = true,
  children,
}: UrgencyGroupProps) {
  const [expanded, setExpanded] = useState(defaultExpanded)
  const meta = URGENCY_META[urgency]

  return (
    <section
      aria-label={`${meta.label} (${count} items)`}
      className={cn('rounded-lg border', meta.borderClass)}
    >
      {/* Group header */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
        className={cn(
          'flex w-full items-center gap-2 rounded-t-lg px-4 py-2.5 transition-colors hover:bg-muted/20',
          !expanded && 'rounded-b-lg',
        )}
      >
        {/* Urgency dot */}
        <span
          className={cn('h-2 w-2 shrink-0 rounded-full', meta.dotClass)}
          aria-hidden="true"
        />

        {/* Label */}
        <span className={cn('text-[11px] font-bold tracking-[0.08em] uppercase', meta.textClass)}>
          {meta.label}
        </span>

        {/* Count badge */}
        <span className={cn('rounded-full px-1.5 py-0.5 text-[10px] font-semibold tabular-nums', meta.badgeBg)}>
          {count}
        </span>

        {/* Expand/collapse chevron */}
        <span className="ml-auto text-muted-foreground/60" aria-hidden="true">
          {expanded
            ? <ChevronDown className="h-3.5 w-3.5" />
            : <ChevronRight className="h-3.5 w-3.5" />
          }
        </span>
      </button>

      {/* Items */}
      {expanded && (
        <div
          className="divide-y divide-border/30 rounded-b-lg"
          role="list"
          aria-label={`${meta.label} items`}
        >
          {children}
        </div>
      )}
    </section>
  )
}

