function initials(name: string): string {
  return name
    .split(' ')
    .map((p) => p[0] ?? '')
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

/**
 * Compact timestamp: "Just now" / "3h ago" / "2d ago" / "In 4d" / "Mar 3"
 */
function compactTimestamp(ts: string): string {
  const date = new Date(ts)
  const nowMs = Date.now()
  const diffMs = nowMs - date.getTime()

  if (isFuture(date)) {
    const futureDiff = date.getTime() - nowMs
    const hours = Math.round(futureDiff / (60 * 60 * 1000))
    if (hours < 24) return `In ${hours}h`
    const days = Math.round(futureDiff / (24 * 60 * 60 * 1000))
    return `In ${days}d`
  }

  if (diffMs < 60 * 1000) return 'Just now'
  if (diffMs < 60 * 60 * 1000) {
    const min = Math.round(diffMs / 60000)
    return `${min}m ago`
  }
  if (diffMs < 24 * 60 * 60 * 1000) {
    const h = Math.round(diffMs / 3600000)
    return `${h}h ago`
  }
  if (diffMs < 7 * 24 * 60 * 60 * 1000) {
    const d = Math.round(diffMs / 86400000)
    return `${d}d ago`
  }
  return format(date, 'MMM d')
}

// Snooze options
const SNOOZE_OPTIONS: { label: string; getValue: () => Date }[] = [
  {
    label: '1 hour',
    getValue: () => new Date(Date.now() + 60 * 60 * 1000),
  },
  {
    label: 'Tomorrow 9 AM',
    getValue: () => {
      const d = new Date()
      d.setDate(d.getDate() + 1)
      d.setHours(9, 0, 0, 0)
      return d
    },
  },
  {
    label: 'Next week',
    getValue: () => {
      const d = new Date()
      d.setDate(d.getDate() + 7)
      d.setHours(9, 0, 0, 0)
      return d
    },
  },
]

export function InboxItemRow({
  item,
  urgency,
  isSelected,
  isFocused,
  members,
  currentUserId,
  onToggleSelect,
  onFocus,
  onRefresh,
}: InboxItemRowProps) {
  const [isPending, startTransition] = useTransition()
  const [showSnoozeMenu, setShowSnoozeMenu] = useState(false)
  const meta = URGENCY_META[urgency]
  const ts = new Date(item.timestamp)

  // Extract the raw UUID from composite id like "booking-<uuid>", "conflict-<uuid>", etc.
  const rawId = item.id.replace(/^(booking|consent|waitlist|client|conflict|inv|conv|payment|guest|birthday|review|artist|gap)-/, '')

  const assignedMember = members.find((m) => m.userId === item.assignedTo) ?? null
  const isUrgentAction = urgency === 'overdue'
  const isHighPriority = item.priority === 'high'

  // ── CTA handler ──
  function handleCta() {
    // For server-action types, fire action. For navigation types, use href.
    const navigateTypes: InboxItemKind[] = [
      'waitlist',
      'unread-message',
      'booking-conflict',
      'artist-gap',
      'low-inventory',
      'client-birthday',
      'failed-payment',
      'guest-residency',
    ]
    if (navigateTypes.includes(item.type)) {
      window.location.href = item.actionHref
      return
    }

    startTransition(async () => {
      let result: { ok: boolean; error?: string }

      if (item.type === 'deposit') {
        result = await sendDepositReminderAction(rawId)
        if (result.ok) {
          toast.success('Deposit reminder sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send reminder')
        }
        return
      }

      if (item.type === 'form') {
        result = await resendFormLinkAction(rawId)
        if (result.ok) {
          toast.success('Form link resent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to resend link')
        }
        return
      }

      if (item.type === 'client' || item.type === 'review-request') {
        result = await sendWelcomeAction(rawId)
        if (result.ok) {
          toast.success(item.type === 'review-request' ? 'Review request sent' : 'Welcome email sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send email')
        }
        return
      }

      window.location.href = item.actionHref
    })
  }

  function handleResolve() {
    startTransition(async () => {
      const result = await resolveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Marked as resolved')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to resolve')
      }
    })
  }

  function handleArchive() {
    startTransition(async () => {
      const result = await archiveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Archived')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to archive')
      }
    })
  }

  async function handleAssign(userId: string | null) {
    const result = await assignInboxItemAction(item.type, rawId, userId)
    if (result.ok) {
      toast.success(userId ? 'Assigned' : 'Unassigned')
      onRefresh()
    } else {
      toast.error(result.error ?? 'Failed to assign')
    }
  }

  function handleSnooze(getValue: () => Date) {
    startTransition(async () => {
      const until = getValue()
      const result = await snoozeInboxItemAction(item.type, rawId, until)
      if (result.ok) {
        const label = formatDistanceToNowStrict(until, { addSuffix: true })
        toast.success(`Snoozed until ${label}`)
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to snooze')
      }
    })
  }

  return (
    <div
      role="listitem"
      data-inbox-item-id={item.id}
      data-selected={isSelected}
      onClick={() => onFocus(item.id)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onFocus(item.id)
        }
      }}
      tabIndex={0}
      className={cn(
        'group flex items-center gap-3 bg-card px-4 py-3 transition-colors',
        'hover:bg-muted/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30',
        isFocused && 'bg-primary/5 ring-1 ring-inset ring-primary/20',
        isSelected && 'bg-primary/5',
        isPending && 'opacity-60',
        'last:rounded-b-lg',
      )}
    >
      {/* Checkbox */}
      <Checkbox
        checked={isSelected}
        onCheckedChange={() => onToggleSelect(item.id)}
        onClick={(e) => e.stopPropagation()}
        aria-label={`Select ${item.title}`}
        className="shrink-0"
      />

      {/* Urgency dot */}
      <span
        className={cn('h-1.5 w-1.5 shrink-0 rounded-full', meta.dotClass)}
        aria-hidden="true"
      />

      {/* Type icon */}
      <div className={cn(
        'flex h-8 w-8 shrink-0 items-center justify-center rounded-full',
        typeBg(item.type, urgency),
      )}>
        {typeIcon(item.type)}
      </div>

      {/* Content */}
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <p className="truncate text-[13px] font-medium text-foreground leading-tight">
            {item.title}
          </p>
          {/* Priority pill */}
          {isHighPriority && (
            <span
              className={cn(
                'shrink-0 inline-flex items-center rounded-full px-1.5 py-px text-[9px] font-bold uppercase tracking-wide',
                isUrgentAction
                  ? 'bg-destructive/10 text-destructive'
                  : 'bg-muted text-muted-foreground',
              )}
              aria-label="High priority"
            >
              HIGH
            </span>
          )}
          {!isHighPriority && !isUrgentAction && (
            <span
              className="shrink-0 inline-flex items-center rounded-full bg-muted/50 px-1.5 py-px text-[9px] font-bold uppercase tracking-wide text-muted-foreground/50"
              aria-label="Medium priority"
            >
              MED
            </span>
          )}
        </div>
        <p className="truncate text-[12px] text-muted-foreground">{item.subtitle}</p>
      </div>

      {/* Assignee avatar */}
      {assignedMember && (
        <Avatar className="h-6 w-6 shrink-0" aria-label={`Assigned to ${assignedMember.name}`}>
          <AvatarFallback className="text-[9px] bg-muted">
            {initials(assignedMember.name)}
          </AvatarFallback>
        </Avatar>
      )}

      {/* Compact timestamp */}
      <time
        dateTime={item.timestamp}
        className="shrink-0 text-[11px] text-muted-foreground/60 hidden sm:block tabular-nums"
        title={format(ts, 'PPpp')}
      >
        {compactTimestamp(item.timestamp)}
      </time>

      {/* One-click CTA */}
      <Button
        variant="outline"
        size="sm"
        onClick={(e) => { e.stopPropagation(); handleCta() }}
        disabled={isPending}
        className={cn(
          'shrink-0 h-7 gap-1.5 text-[11px] hidden sm:flex',
          isUrgentAction && 'border-destructive/40 text-destructive hover:bg-destructive/5 hover:text-destructive',
        )}
        aria-label={`${ctaLabel(item.type)} for ${item.title}`}
      >
        {ctaIcon(item.type)}
        <span className="hidden md:inline">{ctaLabel(item.type)}</span>
      </Button>

      {/* Mobile: icon-only CTA */}
      <Button
        variant="outline"
        size="sm"
        onClick={(e) => { e.stopPropagation(); handleCta() }}
        disabled={isPending}
        className={cn(
          'shrink-0 h-7 w-7 p-0 sm:hidden',
          isUrgentAction && 'border-destructive/40 text-destructive',
        )}
        aria-label={ctaLabel(item.type)}
      >
        {ctaIcon(item.type)}
      </Button>

      {/* Snooze menu trigger — hidden by default, reveal on hover */}
      <DropdownMenu open={showSnoozeMenu} onOpenChange={setShowSnoozeMenu}>
        <DropdownMenuTrigger
          render={
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => { e.stopPropagation(); setShowSnoozeMenu(true) }}
              className="h-7 w-7 shrink-0 p-0 text-muted-foreground/60 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100"
              aria-label="Snooze item"
            >
              <BellOff className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
          }
        />
        <DropdownMenuContent align="end" side="bottom">
          {SNOOZE_OPTIONS.map((opt) => (
            <DropdownMenuItem
              key={opt.label}
              onClick={(e) => {
                e.stopPropagation()
                setShowSnoozeMenu(false)
                handleSnooze(opt.getValue)
              }}
              className="gap-2 text-xs"
            >
              <BellOff className="h-3.5 w-3.5" aria-hidden="true" />
              {opt.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Kebab menu */}
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => e.stopPropagation()}
              className="h-7 w-7 shrink-0 p-0 text-muted-foreground/60 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100"
              aria-label="More options"
            >
              <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
            </Button>
          }
        />
        <DropdownMenuContent align="end" side="bottom">
          <DropdownMenuItem
            onClick={(e) => { e.stopPropagation(); handleResolve() }}
            className="gap-2 text-xs"
          >
            <UserCheck className="h-3.5 w-3.5" aria-hidden="true" />
            Mark resolved
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={(e) => { e.stopPropagation(); handleArchive() }}
            className="gap-2 text-xs"
            aria-label="Archive item"
          >
            <Archive className="h-3.5 w-3.5" aria-hidden="true" />
            Archive
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          {/* View link */}
          <DropdownMenuItem
            className="gap-2 text-xs"
            render={<Link href={item.actionHref} onClick={(e) => e.stopPropagation()} />}
          >
            Open source
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Assign picker — hidden on mobile */}
      <div className="hidden sm:block" onClick={(e) => e.stopPropagation()}>
        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={item.assignedTo}
          onAssign={handleAssign}
          compact
        />
      </div>
    </div>
  )
}

'use client'

import { useTransition } from 'react'
import { Archive, BellOff, CheckCheck, MailOpen, X } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { AssignUserPicker } from './AssignUserPicker'
import type { TeamMember } from './AssignUserPicker'
import type { InboxItemKind } from '@/lib/supabase/types'
import {
  batchResolveAction,
  batchArchiveAction,
  batchAssignAction,
  batchSnoozeAction,
} from '@/app/(app)/inbox/actions'

interface SelectedItem {
  id: string
  type: InboxItemKind
}

interface BatchActionBarProps {
  selected: SelectedItem[]
  members: TeamMember[]
  currentUserId: string
  onClear: () => void
  onRefresh: () => void
}

function toBatchItems(selected: SelectedItem[]) {
  return selected.map((s) => ({
    kind: s.type,
    id: s.id.replace(/^(booking|consent|waitlist|client|conflict|inv|conv|payment|guest|birthday|review|artist|gap)-/, ''),
  }))
}

const SNOOZE_OPTIONS: { label: string; getValue: () => Date }[] = [
  {
    label: '1 hour',
    getValue: () => new Date(Date.now() + 60 * 60 * 1000),
  },
  {
    label: 'Tomorrow 9 AM',
    getValue: () => {
      const d = new Date()
      d.setDate(d.getDate() + 1)
      d.setHours(9, 0, 0, 0)
      return d
    },
  },
  {
    label: 'Next week',
    getValue: () => {
      const d = new Date()
      d.setDate(d.getDate() + 7)
      d.setHours(9, 0, 0, 0)
      return d
    },
  },
]

export function BatchActionBar({
  selected,
  members,
  currentUserId,
  onClear,
  onRefresh,
}: BatchActionBarProps) {
  const [isPending, startTransition] = useTransition()
  const count = selected.length

  if (count === 0) return null

  function handleResolveAll() {
    startTransition(async () => {
      const result = await batchResolveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Resolved ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch resolve failed')
      }
    })
  }

  function handleArchiveAll() {
    startTransition(async () => {
      const result = await batchArchiveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Archived ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch archive failed')
      }
    })
  }

  async function handleAssignAll(userId: string | null) {
    const result = await batchAssignAction(toBatchItems(selected), userId)
    if (result.ok) {
      toast.success(
        userId
          ? `Assigned ${count} item${count > 1 ? 's' : ''}`
          : `Unassigned ${count} item${count > 1 ? 's' : ''}`,
      )
      onClear()
      onRefresh()
    } else {
      toast.error(result.error ?? 'Batch assign failed')
    }
  }

  function handleSnoozeAll(getValue: () => Date) {
    startTransition(async () => {
      const until = getValue()
      const result = await batchSnoozeAction(toBatchItems(selected), until)
      if (result.ok) {
        toast.success(`Snoozed ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch snooze failed')
      }
    })
  }

  return (
    <div
      role="toolbar"
      aria-label="Batch actions"
      aria-live="polite"
      className="flex items-center gap-2 rounded-lg bg-foreground px-4 py-2 text-sm"
    >
      {/* Count + clear */}
      <span className="font-medium text-primary-foreground text-[13px]">
        {count} selected
      </span>
      <button
        type="button"
        onClick={onClear}
        className="flex items-center gap-1 text-primary-foreground/60 hover:text-primary-foreground transition-colors text-xs"
        aria-label="Clear selection"
      >
        <X className="h-3 w-3" aria-hidden="true" />
        Clear
      </button>

      <div className="ml-auto flex items-center gap-2">
        {/* Resolve all */}
        <Button
          size="sm"
          variant="ghost"
          onClick={handleResolveAll}
          disabled={isPending}
          className="h-7 gap-1.5 text-xs text-primary-foreground/80 hover:text-primary-foreground hover:bg-primary-foreground/10"
        >
          <CheckCheck className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Resolve</span>
        </Button>

        {/* Archive all */}
        <Button
          size="sm"
          variant="ghost"
          onClick={handleArchiveAll}
          disabled={isPending}
          aria-label="Archive all selected"
          className="h-7 gap-1.5 text-xs text-primary-foreground/80 hover:text-primary-foreground hover:bg-primary-foreground/10"
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Archive</span>
        </Button>

        {/* Mark as read — for unread-message items */}
        <Button
          size="sm"
          variant="ghost"
          onClick={() => {
            // Resolve all selected (unread-message items get marked resolved = read)
            handleResolveAll()
          }}
          disabled={isPending}
          className="h-7 gap-1.5 text-xs text-primary-foreground/80 hover:text-primary-foreground hover:bg-primary-foreground/10"
        >
          <MailOpen className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Mark as read</span>
        </Button>

        {/* Snooze all */}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                size="sm"
                variant="ghost"
                disabled={isPending}
                className="h-7 gap-1.5 text-xs text-primary-foreground/80 hover:text-primary-foreground hover:bg-primary-foreground/10"
              >
                <BellOff className="h-3.5 w-3.5" aria-hidden="true" />
                <span className="hidden sm:inline">Snooze</span>
              </Button>
            }
          />
          <DropdownMenuContent align="end">
            {SNOOZE_OPTIONS.map((opt) => (
              <DropdownMenuItem
                key={opt.label}
                onClick={() => handleSnoozeAll(opt.getValue)}
                className="gap-2 text-xs"
              >
                <BellOff className="h-3.5 w-3.5" aria-hidden="true" />
                {opt.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>

        {/* Assign to... */}
        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={null}
          onAssign={handleAssignAll}
        />
      </div>
    </div>
  )
}

