export async function batchSnoozeAction(
  items: BatchItem[],
  until: Date,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const dbItems = items.filter((i) => isDBInboxKind(i.kind))
  if (dbItems.length === 0) { revalidatePath('/inbox'); return { ok: true } }

  const rows = dbItems.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind as DBInboxItemKind,
    item_id: i.id,
    snoozed_until: until.toISOString(),
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch snooze failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

